import dynamic from 'next/dynamic';
import { useState } from 'react';

// Defer cart drawer script until the user actually opens it
const CartDrawer = dynamic(() => import('@/components/cart/CartDrawer'), {
  ssr: false,
  loading: () => <div className="p-4 text-sm text-neutral-500">Loading cart...</div>,
});

export function AddToCartSection({ productId }: { productId: string }) {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div className="flex flex-col gap-4">
      <button
        type="button"
        onClick={() => setIsOpen(true)}
        className="rounded-md bg-neutral-900 px-6 py-3 font-medium text-white transition hover:bg-neutral-800"
      >
        Add to Cart
      </button>

      {/* CartDrawer code only downloads when state switches to true */}
      {isOpen && <CartDrawer productId={productId} onClose={() => setIsOpen(false)} />}
    </div>
  );
}

import Image from 'next/image';

interface ProductHeroProps {
  title: string;
  imageUrl: string;
}

export function ProductHero({ title, imageUrl }: ProductHeroProps) {
  return (
    <div className="relative aspect-square w-full max-w-lg overflow-hidden rounded-xl bg-neutral-100">
      <Image
        src={imageUrl}
        alt={title}
        fill
        sizes="(max-width: 768px) 100vw, 512px"
        priority={true} // Injects <link rel="preload"> into HTML head
        className="object-cover"
      />
    </div>
  );
}
